{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile against a plain light background, standing on four thick furry legs. Its overall body shape, fur, head and paws are those of a brown bear, with dense shaggy brown fur that is lighter tan on the muzzle and darker on the limbs, but its back, top of the head, shoulders, hips and shins are covered by a continuous glossy dark brown to nearly black segmented exoskeleton resembling a beetle's armor. A single long, curved, glossy black horn rises from the top of the head. The armor forms overlapping transverse bands over the entire dorsal surface from the head to a short pointed segmented tail, with larger smooth shoulder and hip shields and separate shin guards, while the underside of the chest and belly shows lighter tan segmented plates between the fur and the dark dorsal plates.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a lighter tan muzzle, a black nose at the tip, and small dark brown eyes looking to the right; the top of the head and forehead are covered by a smooth glossy black helmet-like plate",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "a single long, glossy black, sickle-shaped horn with small tooth-like notches along its inner curve, tapering to a sharp point",
      "where": "arising from the center of the glossy head plate on top of the head and arching upward and backward then curving forward over the back"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in light brown fur",
      "where": "protruding from the sides of the head plate just behind and to either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in shaggy brown fur, with the front pair more vertical under the chest and the hind pair slightly angled under the hips",
      "where": "supporting the body from below, two on the near side fully visible and two on the far side partially visible behind them"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with brown fur on top and dark curved claws at the toes, flat on the ground",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short narrow pointed tail made of small overlapping glossy dark rings tapering to a sharp tip and curving slightly downward",
      "where": "at the extreme rear left end of the body, extending from the end of the dorsal armor"
    },
    {
      "part": "shell",
      "looks_like": "a hard glossy dark brown-black carapace forming a continuous dome over the back, composed of overlapping transverse segments with a smooth reflective surface and small circular pores along the lower edge",
      "where": "covering the entire dorsal surface from the back of the neck to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "additional large smooth glossy dark plates: a helmet on the head, a three-lobed shoulder shield over the front back, a hip shield over the hindquarters, and separate shin guards with ridged or spiked lower edges on the front and hind lower legs; plus lighter tan segmented ventral plates with oval openings on the chest, throat and belly",
      "where": "helmet on top of head, shoulder shield behind the neck, hip shield over the hips, shin guards on the outer side of each lower leg, and tan plates on the underside of the neck, chest and abdomen between the fur and the dark dorsal shell"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
